"""Build the complete offline MS-4 HTML reader from extracted pages and source parts."""
from __future__ import annotations
import hashlib,json,re,shutil
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAX_PAGES=16
def write(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def shell(title,body,prefix='',extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | MS-4 reference reader</title><link rel="stylesheet" href="{prefix}assets/reader.css"></head><body><a class="skip" href="#main">Skip to reading</a><header class="top"><a href="{prefix}index.html">MS-4 <span>SEVENTH EDITION</span></a><span>ACCESS IS4S · Reference library</span></header>{body}<footer><p>Asphalt Institute · <em>The Asphalt Handbook</em> · Seventh edition, 2007.</p><p>Original notices, contributor credits and every scanned page are retained. <a href="{prefix}reader/front-matter-01.html#page-0004">Publication notice</a> · <a href="{prefix}README.md">Collection record and editing instructions</a></p></footer><script src="{prefix}assets/reader.js" defer></script>{extra}</body></html>'''
CSS='''
@font-face{font-family:Plex;src:url('fonts/ibm-plex-sans-latin-400-normal.woff2')}@font-face{font-family:Plex;src:url('fonts/ibm-plex-sans-latin-600-normal.woff2');font-weight:600}
:root{--ink:#1A1512;--paper:#F7F4F1;--red:#D2181F;--gold:#FFBC00;--muted:#625D58;--line:#d8d0c9}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 Plex,Arial,sans-serif}a{color:#a71920;text-underline-offset:3px}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--red);outline-offset:4px}.skip{position:absolute;left:-10000px}.skip:focus{left:16px;top:10px;z-index:10;background:white;padding:10px}.top{background:var(--ink);color:white;padding:14px 5vw;display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:5px solid var(--gold)}.top>a{font-size:24px;font-weight:600;text-decoration:none;color:white}.top span{font-size:12px;letter-spacing:.08em}.top>a span{color:var(--gold);margin-left:12px}main,.hero-inner{max-width:1280px;margin:auto;padding:36px 28px}.hero{background:white;border-bottom:1px solid var(--line)}.hero-inner{display:grid;grid-template-columns:minmax(0,1fr) 220px;gap:45px;align-items:center}.hero h1{font-size:clamp(36px,5vw,62px);line-height:1.08;letter-spacing:-.035em;margin:14px 0 20px}.eyebrow{color:#a71920;letter-spacing:.14em;font-size:13px;font-weight:600}.hero img{width:100%;height:auto;box-shadow:0 12px 30px #1a151222}.lead{font-size:21px;max-width:800px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats span{background:#fff5d6;padding:7px 12px;border-bottom:2px solid var(--gold)}h2{font-size:29px;line-height:1.2}h3{line-height:1.3}.notice{border-left:5px solid var(--gold);padding:14px 20px;background:white}.search-box{background:var(--ink);color:white;padding:28px;border-radius:12px}.search-box input{display:block;width:100%;padding:14px;border:2px solid var(--gold);border-radius:5px;margin:12px 0}.search-box button{min-height:44px;padding:9px 18px;border:1px solid var(--gold);border-radius:5px;background:var(--gold);color:var(--ink);font-weight:600;cursor:pointer;margin-right:8px}.search-box button[type=button]{background:transparent;color:white;border-color:#a9a09a}.search-box p{font-size:14px}.search-box a{color:var(--gold)}.results{padding-left:22px}.results li{padding:12px;border-bottom:1px solid var(--line)}.results p{margin:6px 0;font-size:15px;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.chapter{background:white;padding:22px;border:1px solid var(--line);border-top:4px solid var(--red);border-radius:8px}.chapter .number{font-size:34px;color:#a71920;line-height:1}.chapter h3{margin:12px 0}.meta{font-size:14px;color:var(--muted)}.parts{padding-left:18px;font-size:14px}.parts li{margin:6px 0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:22px 0}.toolbar button,.toolbar select,.toolbar a{border:1px solid var(--line);background:white;color:var(--ink);padding:8px 12px;border-radius:5px;text-decoration:none}.toolbar button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}.page{background:white;padding:24px;border:1px solid var(--line);margin:30px 0;border-radius:10px;scroll-margin-top:16px}.page>header{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid var(--gold);margin-bottom:18px;align-items:center}.page h2{font-size:24px}.page-links{font-size:13px;display:flex;gap:12px;flex-wrap:wrap}.page-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start}.scan{margin:0}.scan img{width:100%;height:auto;border:1px solid #e0d8d1}.scan figcaption{font-size:13px;color:var(--muted)}.transcript h3{font-size:16px;margin-top:0}.transcript p{font-size:15px;white-space:pre-wrap;overflow-wrap:anywhere}.confidence{font-size:12px!important;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:12px}.mode-text .scan{display:none}.mode-scan .transcript{display:none}.mode-text .page-grid,.mode-scan .page-grid{grid-template-columns:1fr}.mode-text .transcript{max-width:850px;margin:auto}.mode-scan .scan{max-width:1000px;margin:auto}.pager{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin:28px 0}.pager a{padding:10px 0}.downloads{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--line)}th{background:#fff5d6}footer{max-width:1280px;margin:auto;padding:30px 28px;color:var(--muted);font-size:13px;border-top:1px solid var(--line)}[hidden]{display:none!important}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.page-grid{grid-template-columns:1fr}.hero-inner{grid-template-columns:minmax(0,1fr) 150px}}@media(max-width:600px){main,.hero-inner{padding:24px 14px}.top{padding:12px 14px;align-items:flex-start}.top>span{display:none}.hero-inner{grid-template-columns:1fr}.hero img{display:none}.grid{grid-template-columns:1fr}.page{padding:14px}.page>header{display:block}.page-links{margin-bottom:14px}.search-box{padding:20px}.lead{font-size:18px}.toolbar{gap:6px}.toolbar>*{max-width:100%}.transcript p{font-size:16px}footer{padding:24px 14px}}@media print{body{background:white;font-size:10pt}.top,.toolbar,.pager,.search-box,.skip,footer{display:none}.page{padding:0;border:0;break-before:page}.page-grid{display:block}.scan img{max-height:235mm;object-fit:contain}.page-links{display:none}.transcript p{font-size:10pt}.hero-inner{display:block}.hero img{display:none}.mode-scan .scan{display:block}.page h2{font-size:14pt}}
'''
JS='''
(()=>{'use strict';const buttons=[...document.querySelectorAll('[data-mode]')];buttons.forEach(b=>b.addEventListener('click',()=>{document.body.classList.remove('mode-text','mode-scan');if(b.dataset.mode!=='both')document.body.classList.add('mode-'+b.dataset.mode);buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));const jump=document.querySelector('#page-jump');if(jump)jump.addEventListener('change',()=>{if(jump.value)location.hash=jump.value});const input=document.querySelector('#search');if(!input)return;const output=document.querySelector('#results'),status=document.querySelector('#search-status');let timer;function search(){const q=input.value.trim().toLowerCase();output.replaceChildren();if(q.length<2){status.textContent='Enter at least two characters. Search checks the OCR text of every page.';return}const words=q.split(/\\s+/);const matches=(window.MS4_SEARCH||[]).filter(x=>words.every(w=>x.text.toLowerCase().includes(w)));status.textContent=matches.length+' matching pages'+(matches.length>60?' · showing the first 60':'');matches.slice(0,60).forEach(x=>{const li=document.createElement('li'),a=document.createElement('a'),p=document.createElement('p');a.href=x.href;a.textContent=x.title+' · PDF page '+x.page;const at=x.text.toLowerCase().indexOf(words[0]);p.textContent=(at>80?'…':'')+x.text.slice(Math.max(0,at-80),at+220).replace(/\\s+/g,' ')+'…';li.append(a,p);output.append(li)})}input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(search,150)});document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(timer);search()});document.querySelector('#clear-search').addEventListener('click',()=>{input.value='';search();input.focus()});})();
'''
def main():
 book=json.loads((ROOT/'book-map.json').read_text());parts=json.loads((ROOT/'source-parts.json').read_text())
 records=[]
 for n in range(1,book['pdf_pages']+1):
  r=json.loads((ROOT/'data'/f'p{n:04d}.json').read_text())
  assert r['pdf_page']==n and r['source_sha256']==book['source_sha256']
  assert sha(ROOT/r['text'])==r['text_sha256'] and sha(ROOT/r['image'])==r['image_sha256']
  records.append(r)
 chunks=[]
 for section in book['sections']:
  for i,start in enumerate(range(section['pdf_start'],section['pdf_end']+1,MAX_PAGES),1):
   chunks.append({'file':f'reader/{section["id"]}-{i:02d}.html','title':section['title'],'section':section['id'],
                  'chapter':section['chapter'],'start':start,'end':min(start+MAX_PAGES-1,section['pdf_end']),'part':i})
 page_locations={n:c['file']+f'#page-{n:04d}' for c in chunks for n in range(c['start'],c['end']+1)}
 search=[]
 for index,c in enumerate(chunks):
  pages=[]
  for n in range(c['start'],c['end']+1):
   r=records[n-1];edited=ROOT/'edits'/f'p{n:04d}.txt'
   effective=edited if edited.exists() else ROOT/r['text'];text=effective.read_text()
   r['effective_text']=effective.relative_to(ROOT).as_posix();r['effective_text_sha256']=sha(effective);r['editorial_override']=edited.exists()
   part=next(x for x in parts['parts'] if x['pdf_start']<=n<=x['pdf_end'])
   printed=f' · book page sequence {n-34}' if 35<=n<=823 else ''
   paras=''.join('<p>'+escape(t)+'</p>' for t in re.split(r'\n\s*\n',text.strip()) if t.strip()) or '<p>No words were detected by OCR. Inspect the preserved page image.</p>'
   confidence=f"{r['word_count']} detected words; mean OCR confidence {r['mean_word_confidence']}" if r['word_count'] else 'No OCR words detected'
   if edited.exists():confidence+='; an editorial text override is displayed and the original OCR is retained'
   raw_link=f'<a href="../{r["text"]}" download>Original OCR</a>' if edited.exists() else ''
   pages.append(f'''<article class="page" id="page-{n:04d}"><header><h2>PDF page {n}{printed}</h2><div class="page-links"><a href="../{r['image']}">Enlarge scan</a><a href="../{part['file']}#page={n-part['pdf_start']+1}">Original PDF page</a><a href="../{r['effective_text']}" download>Download text</a>{raw_link}</div></header><div class="page-grid"><figure class="scan"><a href="../{r['image']}"><img src="../{r['image']}" width="{r['image_pixels'][0]}" height="{r['image_pixels'][1]}" loading="lazy" alt="Scanned source PDF page {n}{printed}. Original diagrams, tables and page layout are preserved; OCR transcription is alongside it."></a><figcaption>Original scanned page · select the image to enlarge.</figcaption></figure><div class="transcript"><h3>Searchable transcription</h3><p class="confidence">Unproofread OCR · {confidence}. Check technical values, symbols and table columns against the scan.</p>{paras}</div></div></article>''')
   search.append({'page':n,'title':c['title'],'href':page_locations[n],'text':text})
  prev=chunks[index-1] if index else None;next_=chunks[index+1] if index+1<len(chunks) else None
  pager='<nav class="pager" aria-label="Previous and next reading section">'+(f'<a href="{Path(prev["file"]).name}">← Previous section</a>' if prev else '<span></span>')+f'<a href="../index.html#{c["section"]}">Contents</a>'+(f'<a href="{Path(next_["file"]).name}">Next section →</a>' if next_ else '')+'</nav>'
  toolbar='<div class="toolbar" aria-label="Reading view"><span>View</span><button data-mode="both" aria-pressed="true">Text + scan</button><button data-mode="text" aria-pressed="false">Text</button><button data-mode="scan" aria-pressed="false">Scan</button><label for="page-jump">Page</label><select id="page-jump"><option value="">Choose a page</option>'+''.join(f'<option value="page-{n:04d}">{n}</option>' for n in range(c['start'],c['end']+1))+'</select></div>'
  body=f'<main id="main"><p class="eyebrow">ASPHALT INSTITUTE · MS-4 · 2007</p><h1>{escape(c["title"])}</h1><p>Part {c["part"]} · source PDF pages {c["start"]}–{c["end"]}</p>{pager}{toolbar}{"".join(pages)}{pager}</main>'
  write(ROOT/c['file'],shell(c['title'],body,'../'))
 cards=[]
 for section in book['sections']:
  sc=[c for c in chunks if c['section']==section['id']]
  links=''.join(f'<li><a href="{c["file"]}">Part {c["part"]} · PDF {c["start"]}–{c["end"]}</a></li>' for c in sc)
  label=f'{section["chapter"]:02d}' if section['chapter'] else 'MS-4'
  cards.append(f'<section class="chapter" id="{section["id"]}"><span class="number">{label}</span><h3><a href="{sc[0]["file"]}">{escape(section["title"])}</a></h3><p class="meta">PDF pages {section["pdf_start"]}–{section["pdf_end"]}</p><details><summary>{len(sc)} reading section(s)</summary><ul class="parts">{links}</ul></details></section>')
 downloads=''.join(f'<tr><td>{x["pdf_start"]}–{x["pdf_end"]}</td><td><a href="{x["file"]}">Open original pages</a></td><td>{x["bytes"]/1048576:.2f} MiB</td></tr>' for x in parts['parts'])
 body=f'''<section class="hero"><div class="hero-inner"><div><p class="eyebrow">THE COMPLETE SOURCE BOOK · SEARCHABLE REFERENCE READER</p><h1>The Asphalt Handbook</h1><p class="lead">MS-4 · Seventh edition<br>Asphalt Institute, 2007</p><p class="stats"><span>834 scanned pages</span><span>15 chapters</span><span>{len(chunks)} HTML sections</span></p><p><a href="reader/front-matter-01.html">Begin the book →</a> · <a href="#chapters">Browse chapters</a> · <a href="#source-pdfs">Small source PDFs</a> · <a href="concepts/index.html">Learn the concepts</a></p></div><a href="reader/front-matter-01.html"><img src="assets/pages/p0001.webp" width="1275" height="1650" alt="Original scanned cover of The Asphalt Handbook, MS-4 seventh edition."></a></div></section><main id="main"><p class="notice">Every scanned page, figure, table and publication notice is retained. The transcription is unproofread OCR: use it to search and prepare editable text; check exact technical wording, symbols and table values against the page image or source PDF. The book is the 2007 edition.</p><form class="search-box" id="search-form"><label for="search">Search the entire book</label><input id="search" type="search" placeholder="For example: screed, aggregate, rolling pattern" autocomplete="off"><button type="submit">Search</button> <button type="button" id="clear-search">Clear</button><p id="search-status" role="status" aria-live="polite">Search checks all 834 pages, including the index and contributor credits.</p><noscript>JavaScript is needed for full-book search. All chapter pages and text downloads remain readable without it.</noscript></form><ol id="results" class="results"></ol><h2 id="chapters">Read by chapter</h2><div class="grid">{''.join(cards)}</div><h2 id="source-pdfs">The original scan, in smaller files</h2><p>These {len(parts['parts'])} PDFs preserve all original page content without image resampling. Their ranges use the original viewer page numbers. Inside each part, the PDF viewer starts again at page 1.</p><div class="downloads" tabindex="0" role="region" aria-label="Source PDF parts"><table><thead><tr><th>Original PDF pages</th><th>PDF part</th><th>Size</th></tr></thead><tbody>{downloads}</tbody></table></div><p><a href="source-parts.json">Source-part checksums</a> · <a href="manifest.json">Complete collection manifest</a> · <a href="chapter-map.md">Curriculum alignment</a> · <a href="../index.html">Asphalt curriculum</a></p></main>'''
 write(ROOT/'index.html',shell('The Asphalt Handbook',body,extra='<script src="assets/search-index.js" defer></script>'))
 write(ROOT/'assets/reader.css',CSS);write(ROOT/'assets/reader.js',JS)
 write(ROOT/'assets/search-index.js','window.MS4_SEARCH='+json.dumps(search,ensure_ascii=False,separators=(',',':'))+';\n')
 font_source=ROOT.parent/'assets/fonts';font_target=ROOT/'assets/fonts';font_target.mkdir(exist_ok=True)
 for name in ['ibm-plex-sans-latin-400-normal.woff2','ibm-plex-sans-latin-600-normal.woff2']:
  shutil.copyfile(font_source/name,font_target/name)
 for p in font_source.iterdir():
  if p.suffix.lower() in {'.txt','.md'}:shutil.copyfile(p,font_target/p.name)
 summary={'schema_version':1,**book,'source_parts_file':'source-parts.json','html_sections':chunks,
          'page_locations':{str(k):v for k,v in page_locations.items()},'ocr_policy':records[0]['policy'],
          'ocr_status':'Full-book machine transcription; not fully proofread. Selected curriculum passages are visually checked separately.',
          'word_count':sum(r['word_count'] for r in records),'pages_with_no_detected_words':[r['pdf_page'] for r in records if not r['word_count']],
          'pages_mean_confidence_below_75':[r['pdf_page'] for r in records if r['mean_word_confidence'] is not None and r['mean_word_confidence']<75],
          'display_image_bytes':sum(r['image_bytes'] for r in records),
          'pages':[{k:v for k,v in r.items() if k not in {'words','policy'}} for r in records]}
 write(ROOT/'manifest.json',json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
 print(f"Built {len(chunks)} HTML sections, {len(records)} page images/transcriptions and {len(parts['parts'])} source PDF parts; {summary['word_count']:,} OCR words.")
if __name__=='__main__':main()
